const picker=document.getElementById('deck-picker'),content=document.getElementById('deck-content');let activeDeck=0,activeCombo=0,activeStep=0;

const cardDataCache=new Map();
const detailOverlay=document.getElementById('card-detail-overlay');
const detailDialog=document.getElementById('card-detail-dialog');
const detailClose=document.getElementById('card-detail-close');
let lastCardTrigger=null,currentDetailRequest=0;
function escapeCardText(value){return String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function getCardInfo(name){if(!cardDataCache.has(name)){const request=fetch('https://db.ygoprodeck.com/api/v7/cardinfo.php?name='+encodeURIComponent(name)).then(response=>{if(!response.ok)throw Error('Card lookup failed');return response.json()}).then(data=>{const card=data&&data.data&&data.data[0];if(!card)throw Error('No card details returned');return card}).catch(error=>{cardDataCache.delete(name);throw error});cardDataCache.set(name,request)}return cardDataCache.get(name)}
function renderDecklist(list){const section=(title,cards)=>{const total=cards.reduce((sum,card)=>sum+card[1],0);return '<section class="decklist-group"><div class="decklist-group-heading"><h3>'+title+'</h3><span>'+total+' cards</span></div><div class="deck-card-grid">'+cards.map(([name,qty])=>'<button type="button" class="deck-card-tile" data-card-name="'+escapeCardText(name)+'" aria-label="View details for '+escapeCardText(name)+'; quantity '+qty+'" aria-haspopup="dialog" aria-controls="card-detail-overlay"><span class="deck-card-image-wrap"><img class="deck-card-image" data-card-name="'+escapeCardText(name)+'" alt="'+escapeCardText(name)+' card image" loading="lazy"><span class="deck-card-qty">×'+qty+'</span><span class="deck-card-image-fallback" aria-hidden="true">'+escapeCardText(name.split(' ').slice(0,2).map(x=>x[0]).join(''))+'</span></span><b>'+escapeCardText(name)+'</b></button>').join('')+'</div></section>'};return '<section class="decklist-gallery" id="decklist" aria-label="Fixed decklist"><div class="decklist-gallery-heading"><h2>Decklist</h2></div>'+section('Main Deck',list.main)+section('Extra Deck',list.extra)+(list.bonus?'<p>'+escapeCardText(list.bonus)+'</p>':'')+'</section>'}
function loadDeckCardImages(root=content){const imgs=[...root.querySelectorAll('.deck-card-image[data-card-name]')];const load=img=>{const name=img.dataset.cardName;if(img.dataset.loading)return;img.dataset.loading='true';getCardInfo(name).then(card=>{const image=card.card_images&&card.card_images[0];const url=image&&(image.image_url_small||image.image_url);if(!url)throw Error('No card image');img.src=url;img.classList.add('loaded')}).catch(()=>{img.closest('.deck-card-image-wrap')?.classList.add('image-unavailable')})};if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){load(entry.target);observer.unobserve(entry.target)}}),{rootMargin:'160px'});imgs.forEach(img=>observer.observe(img))}else imgs.forEach(load)}
function getCardTypeLine(card){const type=String(card.type||'').trim();if(type.includes('Monster')){const subtypes=type.replace(/\s*Monster$/i,'').trim().split(/\s+/).filter(Boolean).join(' / ');return [card.race,subtypes].filter(Boolean).join(' / ')}if(type.includes('Spell'))return ['Spell',card.race].filter(Boolean).join(' / ');if(type.includes('Trap'))return ['Trap',card.race].filter(Boolean).join(' / ');return type}
function getCardLevelLabel(card){if(Number(card.linkval)>0)return 'LINK-'+card.linkval;if(card.level!==undefined&&card.level!==null)return (String(card.type||'').toLowerCase().includes('xyz')?'RANK ':'LEVEL ')+card.level;return ''}
function openCardDetails(name,trigger){lastCardTrigger=trigger;detailOverlay.hidden=false;detailDialog.classList.remove('generic-preview');document.body.classList.add('card-detail-open');detailDialog.focus();const requestId=++currentDetailRequest;document.getElementById('card-detail-name').textContent=name;document.querySelector('.card-detail-text-label').textContent='Card text';document.getElementById('card-detail-type').textContent='Loading card details…';document.getElementById('card-detail-description').textContent='Loading card text…';document.getElementById('card-detail-level').hidden=true;document.getElementById('card-detail-attribute').hidden=true;document.getElementById('card-detail-scale').hidden=true;document.getElementById('card-detail-stats').hidden=true;document.getElementById('card-detail-source').hidden=true;const imageElement=document.getElementById('card-detail-image');imageElement.removeAttribute('src');imageElement.alt=name+' card image';document.getElementById('card-detail-media').classList.remove('image-unavailable');getCardInfo(name).then(card=>{if(requestId!==currentDetailRequest)return;document.getElementById('card-detail-name').textContent=card.name||name;const typeLine=document.getElementById('card-detail-type');typeLine.textContent=getCardTypeLine(card);const level=document.getElementById('card-detail-level');const levelLabel=getCardLevelLabel(card);level.textContent=levelLabel;level.hidden=!levelLabel;const attribute=document.getElementById('card-detail-attribute');attribute.textContent=card.attribute||'';attribute.hidden=!card.attribute;const scale=document.getElementById('card-detail-scale');const hasScale=card.scale!==undefined&&card.scale!==null&&String(card.type||'').includes('Pendulum');scale.textContent=hasScale?'Pendulum Scale '+card.scale:'';scale.hidden=!hasScale;document.getElementById('card-detail-description').textContent=card.desc||'';const stats=document.getElementById('card-detail-stats');const isMonster=String(card.type||'').includes('Monster');stats.hidden=!isMonster;if(isMonster){document.getElementById('card-detail-atk').textContent='ATK '+(card.atk??'—');document.getElementById('card-detail-def').textContent='DEF '+(card.def??'—')}const images=card.card_images||[];const fullImage=images[0]&&(images[0].image_url||images[0].image_url_small);if(fullImage){imageElement.src=fullImage;imageElement.alt=(card.name||name)+' full-size card image';imageElement.onerror=()=>document.getElementById('card-detail-media').classList.add('image-unavailable')}const source=document.getElementById('card-detail-source');const officialUrl=card.konami_id?'https://www.db.yugioh-card.com/yugiohdb/card_search.action?ope=2&cid='+encodeURIComponent(card.konami_id)+'&request_locale=en':'https://www.db.yugioh-card.com/yugiohdb/card_search.action?ope=1&keyword='+encodeURIComponent(card.name||name)+'&request_locale=en';source.href=officialUrl;source.hidden=false}).catch(()=>{if(requestId===currentDetailRequest){document.getElementById('card-detail-type').textContent='';document.getElementById('card-detail-description').textContent='Card details could not be loaded. Please try again.'}})}
function openGenericCardPreview(trigger) {
  const data=trigger.dataset;
  lastCardTrigger=trigger;
  detailOverlay.hidden=false;
  detailDialog.classList.add('generic-preview');
  document.body.classList.add('card-detail-open');
  detailDialog.focus();
  currentDetailRequest++;
  document.getElementById('card-detail-name').textContent=data.genericLabel||'Generic card';
  document.getElementById('card-detail-type').textContent=data.genericType||'Any card';
  document.querySelector('.card-detail-text-label').textContent='Type and requirements';
  document.getElementById('card-detail-description').textContent=data.genericRequirements||'This placeholder represents a card with no specific name or artwork.';
  const level=document.getElementById('card-detail-level');
  level.textContent=data.genericLevel||'';
  level.hidden=!data.genericLevel;
  const scale=document.getElementById('card-detail-scale');
  scale.textContent=data.genericScale?'Scale requirement: '+data.genericScale:'';
  scale.hidden=!data.genericScale;
  document.getElementById('card-detail-attribute').hidden=true;
  document.getElementById('card-detail-stats').hidden=true;
  document.getElementById('card-detail-source').hidden=true;
  const image=document.getElementById('card-detail-image');
  image.removeAttribute('src');
  image.alt='';
  document.getElementById('card-detail-media').classList.remove('image-unavailable');
}
function closeCardDetails(){detailOverlay.hidden=true;detailDialog.classList.remove('generic-preview');document.body.classList.remove('card-detail-open');if(lastCardTrigger&&lastCardTrigger.isConnected)lastCardTrigger.focus()}
const pileOverlay=document.getElementById('combo-pile-overlay');
const pileDialog=document.getElementById('combo-pile-dialog');
const pileClose=document.getElementById('combo-pile-close');
const pileList=document.getElementById('combo-pile-card-list');
let lastPileTrigger=null;
function openPileWindow(trigger) {
  let entries=[];
  try { entries=JSON.parse(trigger.dataset.pileEntries||'[]'); } catch (_) { entries=[]; }
  lastPileTrigger=trigger;
  const kind=trigger.dataset.pileKind||'grave';
  const titles={main:'Main Deck cards',extra:'Extra Deck cards',grave:'Graveyard cards',banished:'Banished cards'};
  const title=titles[kind]||'Card list';
  document.getElementById('combo-pile-title').textContent=title;
  document.getElementById('combo-pile-description').textContent=trigger.dataset.pileNote|| (entries.length?'Select a card to open its details or its generic requirements.':'No tracked cards in this zone yet.');
  pileList.innerHTML=entries.map(entry=>comboVisualCardMarkup(entry,'combo-pile-card')).join('');
  pileOverlay.hidden=false;
  document.body.classList.add('combo-pile-open');
  pileDialog.focus();
  loadDeckCardImages(pileList);
}
function closePileWindow() {
  pileOverlay.hidden=true;
  document.body.classList.remove('combo-pile-open');
  if(lastPileTrigger&&lastPileTrigger.isConnected)lastPileTrigger.focus();
}
pileClose.addEventListener('click',closePileWindow);
pileOverlay.addEventListener('click',event=>{if(event.target===pileOverlay)closePileWindow()});
pileList.addEventListener('click',event=>{const generic=event.target.closest('.combo-visual-card[data-generic-preview]');if(generic){openGenericCardPreview(generic);return}const button=event.target.closest('.combo-visual-card[data-card-name]');if(button)openCardDetails(button.dataset.cardName,button)});

content.addEventListener('click',event=>{const tile=event.target.closest('.deck-card-tile[data-card-name]');if(tile)openCardDetails(tile.dataset.cardName,tile)});
detailClose.addEventListener('click',closeCardDetails);
detailOverlay.addEventListener('click',event=>{if(event.target===detailOverlay)closeCardDetails()});
document.addEventListener('keydown',event=>{if(!detailOverlay.hidden&&event.key==='Escape'){event.preventDefault();closeCardDetails();return}if(!pileOverlay.hidden&&event.key==='Escape'){event.preventDefault();closePileWindow();return}if(!pileOverlay.hidden&&event.key==='Tab'){const focusable=[...pileDialog.querySelectorAll('button:not([disabled])')];if(focusable.length){const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}}if(detailOverlay.hidden)return;if(event.key==='Escape'){event.preventDefault();closeCardDetails();return}if(event.key==='Tab'){const focusable=[...detailDialog.querySelectorAll('button:not([disabled]),a[href]:not([hidden])')];if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
function comboVisualCardMarkup(entry, context) {
  const item=typeof entry==='string'?{card:entry}:(entry||{});
  const name=item.card||'';
  const displayName=item.label||name||'Card';
  const specific=Boolean(name);
  const frame=item.frame||'any';
  const meta=item.level||item.scale||'';
  const qty=Number(item.qty)>1?'<span class="deck-card-qty">×'+Number(item.qty)+'</span>':'';
  const isDiscardCard=!specific&&/discard/i.test(displayName+' '+(item.requirements||''));
  const common=' class="deck-card-image-wrap combo-visual-card-frame';
  const frameOpen=specific||isDiscardCard
    ? '<span'+common+(isDiscardCard?' combo-discard-frame':'')+'">'
    : '<span'+common+' combo-generic-frame" data-generic-frame="'+escapeCardText(frame)+'">';
  const art=specific
    ? '<img class="deck-card-image" data-card-name="'+escapeCardText(name)+'" alt="'+escapeCardText(name)+' card image" loading="lazy"><span class="deck-card-image-fallback" aria-hidden="true">'+escapeCardText(name.split(/\s+/).slice(0,2).map(x=>x[0]||'').join(''))+'</span>'
    : isDiscardCard?'<img class="combo-card-back-art" src="card-back.svg" alt="Yu-Gi-Oh! card back" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="combo-card-back-fallback" hidden aria-hidden="true"></span>':'<span class="combo-generic-art" aria-hidden="true"></span>'+(meta?'<span class="combo-generic-meta">'+escapeCardText(meta)+'</span>':'');
  const button=specific
    ? '<button type="button" class="combo-visual-card '+context+'" data-card-name="'+escapeCardText(name)+'" aria-label="View card details for '+escapeCardText(name)+'" aria-haspopup="dialog" aria-controls="card-detail-overlay">'
    : '<button type="button" class="combo-visual-card combo-generic-card '+context+'" data-generic-preview data-generic-label="'+escapeCardText(displayName)+'" data-generic-type="'+escapeCardText(item.type||'Any card')+'" data-generic-frame="'+escapeCardText(frame)+'" data-generic-level="'+escapeCardText(item.level||'')+'" data-generic-scale="'+escapeCardText(item.scale||'')+'" data-generic-requirements="'+escapeCardText(item.requirements||'This placeholder represents a card with no specific name or artwork.')+'" aria-label="View type and requirements for '+escapeCardText(displayName)+'" aria-haspopup="dialog" aria-controls="card-detail-overlay">';
  return button+frameOpen+art+qty+'</span><span class="combo-visual-card-name">'+escapeCardText(displayName)+'</span></button>';
}
function comboStartingHandMarkup(entries) {
  return (entries||[]).flatMap(entry=>{
    const item=typeof entry==='string'?{card:entry}:(entry||{});
    const count=Math.max(1,Math.min(10,Number(item.qty)||1));
    return Array.from({length:count},()=>Object.assign({},item,{qty:1}));
  }).map(item=>comboVisualCardMarkup(item,'combo-hand-card')).join('');
}
function pileCount(entries) { return (entries||[]).reduce((sum,entry)=>sum+Math.max(1,Number(entry&&entry.qty)||1),0); }
function pileIconMarkup(kind, entries, topEntry) {
  const back='card-back.svg';
  if(kind==='main'||(kind==='extra'&&!topEntry))return '<img class="combo-pile-top-image" src="'+back+'" alt="Yu-Gi-Oh! card back" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="combo-card-back-fallback" hidden aria-hidden="true"></span>';
  if(topEntry&&topEntry.card)return '<img class="combo-pile-top-image deck-card-image" data-card-name="'+escapeCardText(topEntry.card)+'" alt="Most recent card: '+escapeCardText(topEntry.card)+'" loading="lazy"><span class="deck-card-image-fallback" aria-hidden="true">'+escapeCardText(topEntry.card.split(/\s+/).slice(0,2).map(x=>x[0]||'').join(''))+'</span>';
  if(topEntry)return '<span class="combo-pile-top-generic combo-generic-frame" data-generic-frame="'+escapeCardText(topEntry.frame||'any')+'"><span class="combo-generic-art"></span>'+(topEntry.scale||topEntry.level?'<span class="combo-generic-meta">'+escapeCardText(topEntry.scale||topEntry.level)+'</span>':'')+'</span>';
  return '<span class="combo-zone-empty">Empty</span>';
}
function comboPileZoneMarkup(zone, value) {
  let entries=[],count=0,topEntry=null,note='';
  const kind=zone.key;
  if(value===undefined)return '<div class="combo-field-zone combo-pile-zone"><span class="combo-zone-label">'+zone.label+'</span><span class="combo-zone-empty">Not tracked</span></div>';
  if(kind==='main'||kind==='extra'){
    entries=value&&value.entries||[];count=value&&value.count||0;topEntry=value&&value.topEntry||null;note=value&&value.note||'';
  } else {
    entries=Array.isArray(value)?value:[];count=pileCount(entries);topEntry=entries.length?entries[entries.length-1]:null;
    note=entries.length?'The last card shown is the most recently added card. Select any card to open its details.':'No cards are currently tracked in this pile.';
  }
  const names=entries.map(entry=>entry.card||entry.label||'Card').join(', ');
  const icon=pileIconMarkup(kind,entries,topEntry);
  const body=count?'<button type="button" class="combo-pile-trigger" data-pile-kind="'+kind+'" data-pile-count="'+count+'" data-pile-note="'+escapeCardText(note)+'" data-pile-entries="'+escapeCardText(JSON.stringify(entries))+'" aria-label="Open '+zone.label+' card list, '+count+' cards"><span class="combo-pile-top">'+icon+'</span><b>'+count+' '+(count===1?'card':'cards')+'</b><span>View cards</span></button>':'<span class="combo-zone-empty">Empty</span>';
  return '<div class="combo-field-zone combo-pile-zone'+(count?' occupied':'')+'" aria-label="'+zone.label+(count?': '+escapeCardText(names):': empty')+'"><span class="combo-zone-label">'+zone.label+'</span>'+body+'</div>';
}
function comboFieldBoardMarkup(field, heading, note, handEntries) {
  const rows=[
    [{key:null,label:'',empty:true},{key:null,label:'',empty:true},{key:'emzLeft',label:'Extra Monster Zone'},{key:null,label:'',empty:true},{key:'emzRight',label:'Extra Monster Zone'},{key:null,label:'',empty:true},{key:'banished',label:'Banished'}],
    [{key:'field',label:'Field Zone'},{key:'monster1',label:'Monster Zone'},{key:'monster2',label:'Monster Zone'},{key:'monster3',label:'Monster Zone'},{key:'monster4',label:'Monster Zone'},{key:'monster5',label:'Monster Zone'},{key:'grave',label:'Graveyard'}],
    [{key:'extra',label:'Extra Deck'},{key:'spell1',label:'Spell / Trap Zone'},{key:'spell2',label:'Spell / Trap Zone'},{key:'spell3',label:'Spell / Trap Zone'},{key:'spell4',label:'Spell / Trap Zone'},{key:'spell5',label:'Spell / Trap Zone'},{key:'main',label:'Main Deck'}]
  ];
  const html=rows.map(row=>row.map(zone=>{
    if(zone.empty)return '<div class="combo-field-zone combo-field-empty-space" aria-hidden="true"></div>';
    const value=field&&field[zone.key];
    if(['grave','banished','main','extra'].includes(zone.key))return comboPileZoneMarkup(zone,value);
    const item=typeof value==='string'?{card:value}:value;
    const occupied=item&&(item.card||item.label),displayName=occupied?(item.label||item.card):'';
    const body=occupied?comboVisualCardMarkup(item,'combo-zone-card')+
      (item.materials&&item.materials.length?'<span class="combo-material-note">'+item.materials.map(x=>(x.qty||1)+' '+escapeCardText(x.card||x.label||x)).join(', ')+'</span>':'')+(item.note?'<span class="combo-material-note">'+escapeCardText(item.note)+'</span>':''):
      '<span class="combo-zone-empty">Empty</span>';
    return '<div class="combo-field-zone'+(occupied?' occupied':'')+'" aria-label="'+zone.label+(occupied?': '+escapeCardText(displayName):': empty')+'"><span class="combo-zone-label">'+zone.label+'</span>'+body+'</div>';
  }).join('')).join('');
  const handMarkup=Array.isArray(handEntries)?'<section class="combo-field-hand" aria-label="Hand after '+escapeCardText(heading)+'"><div class="combo-field-hand-heading"><b>Hand</b><span>'+pileCount(handEntries)+' '+(pileCount(handEntries)===1?'card':'cards')+'</span></div><div class="combo-field-hand-cards">'+(handEntries.length?comboStartingHandMarkup(handEntries):'<span class="combo-hand-empty">No tracked cards in hand</span>')+'</div></section>':'';
  return '<section class="combo-visual-panel combo-field-panel"><div class="combo-visual-panel-heading"><h3>'+heading+'</h3>'+(note?'<p>'+escapeCardText(note)+'</p>':'')+'</div><div class="combo-field-grid" role="group" aria-label="'+heading+' board state">'+html+'</div>'+handMarkup+'</section>';
}
function comboTextOnlyMarkup(combo, stepIndex, visual) {
  const handVisual = visual?.hand || [];
  const describeField = field => Object.values(field || {}).map(card=>card?.card || card?.label || (typeof card==='string'?card:'')).filter(Boolean).join(', ');
  const playerField = visual ? (describeField(visual.fieldBefore) || 'Empty') : '';
  const opponentField = describeField(visual?.opponentBefore);
  const discardCount=(handVisual||[]).filter(item=>item&&!item.card&&/discard/i.test((item.label||'')+' '+(item.requirements||''))).reduce((sum,item)=>sum+Math.max(1,Number(item.qty)||1),0);
  const backArt=discardCount?'<div class="combo-mobile-cardbacks" role="img" aria-label="Card-back placeholders for generic discard cards">'+Array.from({length:discardCount},()=>'<span class="combo-mobile-cardback"><img class="combo-card-back-art" src="card-back.svg" alt="Yu-Gi-Oh! card back" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="combo-card-back-fallback" hidden aria-hidden="true"></span></span>').join('')+'</div>':'';
  const setup = '<div class="opening-hand"><b>Starting hand</b><span>'+escapeCardText(combo.hand)+'</span>'+backArt+'</div>'+
    (playerField?'<div class="line-condition"><b>Your field</b><span>'+escapeCardText(playerField)+'</span></div>':'')+
    (opponentField?'<div class="line-condition"><b>Opponent’s field</b><span>'+escapeCardText(opponentField)+'</span></div>':'')+
    '<div class="line-condition"><b>Before you start</b><span>'+escapeCardText(combo.condition)+'</span></div>';
  const step = stepIndex === 0 ? '<div>'+setup+'</div>' : '<p>'+escapeCardText(combo.steps[stepIndex-1])+'</p>';
  return '<div class="combo-text-only"><article class="line-step current"><span>STEP '+stepIndex+'</span>'+step+'</article>'+
    comboResultAndControls(combo,stepIndex)+'</div>';
}

function comboResultAndControls(combo, stepIndex) {
  return '<div class="line-result"><b>Line result</b><span>'+escapeCardText(combo.result)+'</span></div><div class="combo-actions">'+
    '<button type="button" class="line-prev" '+(stepIndex===0?'disabled':'')+'>← Previous</button><span class="step-count">STEP '+stepIndex+' OF '+combo.steps.length+'</span>'+
    '<button type="button" class="line-next next">'+(stepIndex===combo.steps.length?'Restart line ↺':'Next step →')+'</button></div>';

}
function comboBoardZones(field, state, deckListsForDeck, baseHandNames) {
  const source=deckListsForDeck||{main:[],extra:[]};
  const removeCounts=list=>{const counts=new Map();(list||[]).forEach(entry=>{const name=typeof entry==='string'?entry:entry.card;if(name)counts.set(name,(counts.get(name)||0)+Math.max(1,Number(entry.qty)||1))});return counts};
  const mainRemoved=removeCounts([...(baseHandNames||[]),...((state&&state.mainRemoved)||[])]);
  const mainEntries=[];
  (source.main||[]).forEach(([name,qty])=>{const left=Math.max(0,qty-(mainRemoved.get(name)||0));if(left)mainEntries.push({card:name,qty:left})});
  const extraRemoved=removeCounts((state&&state.extraRemoved)||[]),extraEntries=[];
  (source.extra||[]).forEach(([name,qty])=>{const left=Math.max(0,qty-(extraRemoved.get(name)||0));if(left)extraEntries.push({card:name,qty:left})});
  const faceUp=(state&&state.extraFaceUp)||[];
  const mainTotal=Math.max(0,pileCount(mainEntries)-(Number(state&&state.mainUnknownRemoved)||0));
  const mainUnknown=Number(state&&state.mainUnknownRemoved)||0;
  const mainNote=mainUnknown?'The fixed list is shown minus named cards; '+mainUnknown+' unidentified card'+(mainUnknown===1?' is':'s are')+' also out of the Main Deck, so its exact identity is not known.':'The list shows cards remaining after the named cards tracked in this combo.';
  const extraUnknown=Number(state&&state.extraUnknownRemoved)||0;
  const extraTotal=Math.max(0,pileCount(extraEntries)+pileCount(faceUp)-extraUnknown);
  const extraNote=(faceUp.length?'Face-up Pendulum cards are listed last; the most recent Pendulum card appears as the pile icon.':'The most recent card is not knowable while the Extra Deck is face-down, so its icon uses the card back.')+(extraUnknown?' '+extraUnknown+' unidentified Extra Deck card'+(extraUnknown===1?' is':'s are')+' also out of the Deck.':'');
  return Object.assign({},field||{}, {
    grave:state&&state.grave||[],banished:state&&state.banished||[],
    main:{entries:mainEntries,count:mainTotal,note:mainNote},
    extra:{entries:extraEntries.concat(faceUp),count:extraTotal,topEntry:faceUp.length?faceUp[faceUp.length-1]:null,note:extraNote}
  });
}
function comboVisualMarkup(combo, visual, stepIndex) {
  const steps = ['Starting hand & fields', ...visual.steps.map((item,i)=>item.flow?.action || 'Step '+(i+1))];
  const nav = '<nav class="combo-visual-step-nav" aria-label="Choose a combo step">'+steps.map((label,i)=>
    '<button type="button" class="'+(i===stepIndex?'active':'')+'" data-visual-step="'+i+'" aria-current="'+(i===stepIndex?'step':'false')+'"><span>'+String(i).padStart(2,'0')+'</span>'+escapeCardText(label)+'</button>').join('')+'</nav>';
  const mainOpenerNames=(visual.hand||[]).concat(Object.values(visual.fieldBefore||{})).flatMap(item=>item&&item.card?Array.from({length:Math.max(1,Number(item.qty)||1)},()=>item.card):[]);
  const openingUnknown=(visual.hand||[]).concat(Object.values(visual.fieldBefore||{})).filter(item=>item&&!item.card).reduce((sum,item)=>sum+Math.max(1,Number(item.qty)||1),0);
  const startingState={hand:visual.hand||[],grave:[],banished:[],mainUnknownRemoved:openingUnknown};
  const startingBoard=comboBoardZones(Object.assign({},visual.fieldBefore||{},{grave:[],banished:[]}),startingState,visual.deckLists,mainOpenerNames);
  let body;
  if (stepIndex === 0) {
    body = '<section class="combo-visual-panel"><h3>Step 0 · Starting hand &amp; fields</h3><p>'+escapeCardText(combo.condition)+'</p></section>'+
      '<section class="combo-visual-panel"><div class="combo-visual-panel-heading"><h3>Starting hand</h3></div><div class="combo-hand-cards">'+comboStartingHandMarkup(visual.hand)+'</div></section>'+
      comboFieldBoardMarkup(startingBoard,'Starting field','')+
      (visual.opponentBefore?comboFieldBoardMarkup(visual.opponentBefore,'Opponent starting field',''):'');
  } else {
    const i = stepIndex - 1;
    const step = visual.steps[i], flow = step.flow || {};
    const piles = visual.piles[i] || {}, zoneState = visual.zoneStates[i] || {};
    const stepState = {...zoneState,grave:piles.grave||[],banished:piles.banished||[],mainUnknownRemoved:openingUnknown+(Number(zoneState.mainUnknownRemoved)||0)};
    const stepBoard = comboBoardZones(step.fieldAfter||{},stepState,visual.deckLists,mainOpenerNames);
    const inputs = flow.inputs || [], outputs = flow.outputs || [];
    const cards = entries => '<div class="combo-flow-cards">'+entries.map(card=>comboVisualCardMarkup(card,'combo-flow-card')).join('')+'</div>';
    const hasArrow = inputs.length && outputs.length && !flow.showSourceOnly;
    const diagram = hasArrow
      ? '<div class="combo-card-flow">'+cards(inputs)+'<div class="combo-flow-arrow"><span>'+escapeCardText(flow.action||'')+'</span><b aria-hidden="true">→</b></div>'+cards(outputs)+'</div>'
      : '<div class="combo-scale-activation">'+cards(inputs.length?inputs:outputs)+'<strong>'+escapeCardText(flow.action||'')+'</strong></div>';
    body = '<section class="combo-visual-panel combo-step-visual-panel"><div class="combo-visual-panel-heading"><h3>Step '+stepIndex+' of '+combo.steps.length+'</h3><p>'+escapeCardText(combo.steps[i])+'</p></div>'+diagram+'</section>'+
      comboFieldBoardMarkup(stepBoard,'Step '+stepIndex,'',zoneState.hand||[])+
      (step.opponentAfter?comboFieldBoardMarkup(step.opponentAfter,'Opponent field after step '+stepIndex,''):'');
  }
  return '<div class="combo-visual-desktop">'+nav+body+comboResultAndControls(combo,stepIndex)+'</div>'+comboTextOnlyMarkup(combo,stepIndex,visual);
}
function renderDeck() {
  const deck=decks[activeDeck];
  picker.innerHTML=decks.map((item,i)=>'<button role="tab" aria-selected="'+(i===activeDeck)+'" class="'+(i===activeDeck?'active':'')+'" data-deck="'+i+'"><b>'+escapeCardText(item.name)+'</b><span>'+escapeCardText(item.product?.startsWith('THE CHRONICLES DECK')?'The Chronicles Deck':item.product||'Custom Deck')+'</span></button>').join('');
  picker.querySelectorAll('[data-deck]').forEach(button=>button.addEventListener('click',()=>{activeDeck=Number(button.dataset.deck);activeCombo=0;activeStep=0;renderDeck()}));
  const combo=deck.combos[activeCombo];
  if(combo)activeStep=Math.min(activeStep,combo.steps.length);
  const key=combo && deck.id+'|'+combo.title;
  const visual=(window.comboVisuals||{})[key];
  if(visual){visual.piles=(window.comboPileStates||{})[key]||visual.steps.map(()=>({grave:[],banished:[]}));visual.zoneStates=(window.comboZoneStates||{})[key]||visual.steps.map(()=>({hand:[]}));visual.deckLists=deckLists[deck.id];}
  const markup=combo?(visual?comboVisualMarkup(combo,visual,activeStep):comboTextOnlyMarkup(combo,activeStep)):'<p>No combo lines are available for this deck yet.</p>';
  content.innerHTML='<article class="deck-overview"><div class="deck-art '+deck.id+'"><img class="boss-art" src="'+deck.art+'" alt="'+escapeCardText(deck.boss)+' card artwork" loading="lazy"><b>'+escapeCardText(deck.boss)+'</b><small>'+escapeCardText(deck.name+' · '+deck.subtitle)+'</small></div><div class="deck-summary"><h2>'+escapeCardText(deck.name)+'</h2><div class="deck-facts"><span class="deck-fact">'+escapeCardText(deck.fixed)+'</span><span class="deck-fact">'+escapeCardText(deck.playstyle)+'</span></div><div class="deck-section-jumps"><a href="#decklist">View Decklist</a><a href="#combo-lines">View Combo Lines</a></div></div></article>'+renderDecklist(deckLists[deck.id])+
    '<section class="combo-tutorial'+(visual?' has-visual':'')+'" id="combo-lines"><div class="section-heading"><div><h2>Combo Lines</h2></div></div>'+
    '<div class="combo-tabs">'+deck.combos.map((item,i)=>'<button type="button" class="'+(i===activeCombo?'active':'')+'" data-combo="'+i+'">'+(i+1)+'. '+escapeCardText(item.title)+'</button>').join('')+'</div><div class="line-card">'+markup+'</div></section>';
  loadDeckCardImages();
  content.querySelectorAll('[data-combo]').forEach(button=>button.addEventListener('click',()=>{activeCombo=Number(button.dataset.combo);activeStep=0;renderDeck()}));
  content.querySelectorAll('[data-visual-step]').forEach(button=>button.addEventListener('click',()=>{activeStep=Number(button.dataset.visualStep);renderDeck()}));
  content.querySelectorAll('.line-prev').forEach(button=>button.addEventListener('click',()=>{activeStep=Math.max(0,activeStep-1);renderDeck()}));
  content.querySelectorAll('.line-next').forEach(button=>button.addEventListener('click',()=>{activeStep=activeStep===combo.steps.length?0:activeStep+1;renderDeck()}));
}
content.addEventListener('click',event=>{const pile=event.target.closest('.combo-pile-trigger');if(pile){openPileWindow(pile);return}const generic=event.target.closest('.combo-visual-card[data-generic-preview]');if(generic){openGenericCardPreview(generic);return}const button=event.target.closest('.combo-visual-card[data-card-name]');if(button)openCardDetails(button.dataset.cardName,button)});
renderDeck();
